grant create on schema api,app_private to git_tutor_commands;
create table app_private.crm_customers(learner_id uuid primary key references app_private.learners(id),archived boolean not null default false,version integer not null default 1);
create table app_private.follow_ups(id uuid primary key default gen_random_uuid(),learner_id uuid not null references app_private.learners(id),owner_id uuid not null references app_private.accounts(id),due_at timestamptz not null,reason text not null,channel text not null check(channel in('email','phone','whatsapp','portal')),state text not null default'open'check(state in('open','completed','cancelled')),version integer not null default 1,created_at timestamptz not null default now(),completed_at timestamptz);
create table app_private.follow_up_resolutions(id uuid primary key default gen_random_uuid(),follow_up_id uuid not null unique references app_private.follow_ups(id),actor_id uuid not null references app_private.accounts(id),resolution text not null,created_at timestamptz not null default now());
create index follow_up_owner_queue on app_private.follow_ups(owner_id,state,due_at);
create function app_private.crm_can_access(p_actor uuid,p_learner uuid)returns boolean language sql stable security definer set search_path='' as $$select app_private.has_role(p_actor,'admin')or(app_private.has_role(p_actor,'customer_service')and(exists(select 1 from app_private.follow_ups f where f.learner_id=p_learner and f.owner_id=p_actor and f.state='open')or exists(select 1 from app_private.review_cases c join app_private.receipts r on r.id=c.receipt_id where r.learner_id=p_learner and c.owner_id=p_actor and c.claim_expires_at>now()and c.state in('claimed','needs_information'))))$$;
create function app_private.crm_customer_dto(p_actor uuid,p_learner uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare item jsonb;begin
 if not app_private.crm_can_access(p_actor,p_learner)then raise exception'NOT_FOUND';end if;
 select jsonb_build_object('learner_id',l.id,'person_id',l.person_id,'account_id',l.account_id,'display_name',p.display_name,'version',coalesce(c.version,1),'archived',coalesce(c.archived,false),'verified_contacts',(select coalesce(jsonb_agg(jsonb_build_object('channel',v.channel,'destination',v.destination,'verified',true)order by v.id),'[]'::jsonb)from app_private.verified_contacts v where v.account_id=l.account_id and v.revoked_at is null and v.verified_at is not null),'possible_duplicate_count',0,'open_follow_up_count',(select count(*)from app_private.follow_ups f where f.learner_id=l.id and f.state='open'),'balance_minor',finance_private.finance_json_total((select coalesce(sum((finance_private.finance_charge_balance(ch.id)->>'receivable_minor')::numeric),0)from finance_private.charges ch where ch.learner_id=l.id)))into item from app_private.learners l join app_private.people p on p.id=l.person_id left join app_private.crm_customers c on c.learner_id=l.id where l.id=p_learner;
 if item is null then raise exception'NOT_FOUND';end if;return item;end$$;
create function api.list_customers(p_q text default null,p_owner_id uuid default null,p_has_balance boolean default null,p_archived boolean default false,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb;begin
 if not app_private.support_staff(actor)then raise exception'FORBIDDEN';end if;if p_limit is null or p_limit not between 1 and 100 or length(p_q)>200 then raise exception'VALIDATION_ERROR';end if;
 select coalesce(jsonb_agg(x.item order by x.id),'[]'::jsonb)into items from(select l.id,app_private.crm_customer_dto(actor,l.id)item from app_private.learners l join app_private.people p on p.id=l.person_id left join app_private.crm_customers c on c.learner_id=l.id where app_private.crm_can_access(actor,l.id)and coalesce(c.archived,false)=coalesce(p_archived,false)and(p_cursor is null or l.id>p_cursor)and(p_q is null or p_q=''or l.id::text=p_q or p.display_name ilike'%'||p_q||'%'or exists(select 1 from app_private.verified_contacts v where v.account_id=l.account_id and v.verified_at is not null and v.revoked_at is null and v.destination ilike'%'||p_q||'%'))and(p_owner_id is null or exists(select 1 from app_private.follow_ups f where f.learner_id=l.id and f.owner_id=p_owner_id and f.state='open'))and(p_has_balance is null or((app_private.crm_customer_dto(actor,l.id)->>'balance_minor')::numeric>0)=p_has_balance)order by l.id limit p_limit)x;
 return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'learner_id'else null end);end$$;
create function api.get_customer(p_learner_id uuid,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();customer jsonb;items jsonb;begin
 customer:=app_private.crm_customer_dto(actor,p_learner_id);if p_limit is null or p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;
 with history as(select e.id,'enrollment'::text kind,e.created_at at,e.id reference,'Booking: '||s.title summary from app_private.enrollments e join app_private.occurrences o on o.id=e.occurrence_id join app_private.offers f on f.id=o.offer_id join app_private.subjects s on s.id=f.subject_id where e.learner_id=p_learner_id union all select r.id,'receipt',r.created_at,r.id,'Payment evidence submitted'from app_private.receipts r where r.learner_id=p_learner_id union all select f.id,'follow_up',f.created_at,f.id,'Follow-up: '||f.state from app_private.follow_ups f where f.learner_id=p_learner_id)
 select coalesce(jsonb_agg(x.item order by x.id),'[]'::jsonb)into items from(select id,jsonb_build_object('event_id',id,'event_type',kind,'occurred_at',at,'reference_id',reference,'summary',summary)item from history where p_cursor is null or id>p_cursor order by id limit p_limit)x;
 return jsonb_build_object('customer',customer,'history_page',jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'event_id'else null end));end$$;
create function api.assign_follow_up(p_learner_id uuid,p_owner_id uuid,p_due_at timestamptz,p_reason text,p_channel text,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;v integer;fid uuid:=gen_random_uuid();begin
 if not app_private.crm_can_access(actor,p_learner_id)then raise exception'NOT_FOUND';end if;if not app_private.support_staff(p_owner_id)or(not app_private.has_role(actor,'admin')and p_owner_id<>actor)then raise exception'FORBIDDEN';end if;
 ctx:=app_private.booking_begin(actor,'assign_follow_up',jsonb_build_object('learner_id',p_learner_id,'owner_id',p_owner_id,'due_at',p_due_at,'reason',p_reason,'channel',p_channel,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if p_due_at is null or not isfinite(p_due_at)or p_due_at<=now()then raise exception'INVALID_TIME';end if;if p_reason is null or length(btrim(p_reason))not between 1 and 2000 or p_channel is null or p_channel not in('email','phone','whatsapp','portal')then raise exception'VALIDATION_ERROR';end if;
 insert into app_private.crm_customers(learner_id)values(p_learner_id)on conflict do nothing;select version into v from app_private.crm_customers where learner_id=p_learner_id for update;if v is distinct from p_expected_version then raise exception'VERSION_CONFLICT';end if;
 insert into app_private.follow_ups(id,learner_id,owner_id,due_at,reason,channel)values(fid,p_learner_id,p_owner_id,p_due_at,btrim(p_reason),p_channel);update app_private.crm_customers set version=version+1 where learner_id=p_learner_id returning version into v;
 return app_private.booking_finish(ctx,p_learner_id,v,jsonb_build_object('follow_up_id',fid),'follow_up_assigned',jsonb_build_object('follow_up_id',fid));end$$;
create function api.complete_follow_up(p_follow_up_id uuid,p_resolution text,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;f app_private.follow_ups%rowtype;begin
 select * into f from app_private.follow_ups where id=p_follow_up_id for update;if f.id is null then raise exception'NOT_FOUND';end if;if not app_private.has_role(actor,'admin')and not(app_private.has_role(actor,'customer_service')and f.owner_id=actor)then raise exception'FORBIDDEN';end if;
 ctx:=app_private.booking_begin(actor,'complete_follow_up',jsonb_build_object('follow_up_id',p_follow_up_id,'resolution',p_resolution,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;if f.version is distinct from p_expected_version then raise exception'VERSION_CONFLICT';end if;if f.state<>'open'then raise exception'STATE_CONFLICT';end if;if p_resolution is null or length(btrim(p_resolution))not between 1 and 2000 then raise exception'VALIDATION_ERROR';end if;
 insert into app_private.follow_up_resolutions(follow_up_id,actor_id,resolution)values(f.id,actor,btrim(p_resolution));update app_private.follow_ups set state='completed',completed_at=now(),version=version+1 where id=f.id;
 return app_private.booking_finish(ctx,f.id,f.version+1,jsonb_build_object('state','completed'),'follow_up_completed',jsonb_build_object('follow_up_id',f.id));end$$;
create function api.set_customer_archived(p_learner_id uuid,p_archived boolean,p_reason text,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;v integer;begin
 perform app_private.require_role(actor,'admin');if not exists(select 1 from app_private.learners where id=p_learner_id)then raise exception'NOT_FOUND';end if;ctx:=app_private.booking_begin(actor,'set_customer_archived',jsonb_build_object('learner_id',p_learner_id,'archived',p_archived,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if p_archived is null or p_reason is null or length(btrim(p_reason))not between 1 and 2000 then raise exception'VALIDATION_ERROR';end if;insert into app_private.crm_customers(learner_id)values(p_learner_id)on conflict do nothing;select version into v from app_private.crm_customers where learner_id=p_learner_id for update;if v is distinct from p_expected_version then raise exception'VERSION_CONFLICT';end if;update app_private.crm_customers set archived=p_archived,version=version+1 where learner_id=p_learner_id;
 return app_private.booking_finish(ctx,p_learner_id,v+1,jsonb_build_object('archived',p_archived),'customer_archive_changed',jsonb_build_object('learner_id',p_learner_id));end$$;
create function api.list_crm_owners()returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb;begin
 if not app_private.support_staff(actor)then raise exception'FORBIDDEN';end if;select coalesce(jsonb_agg(jsonb_build_object('account_id',a.id,'display_name',p.display_name)order by p.display_name,a.id),'[]'::jsonb)into items from app_private.accounts a join app_private.people p on p.id=a.person_id where a.active and app_private.support_staff(a.id)and(app_private.has_role(actor,'admin')or a.id=actor);return jsonb_build_object('items',items,'next_cursor',null);end$$;
create function api.list_follow_ups(p_learner_id uuid default null,p_owner_id uuid default null,p_state text default null,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb;begin
 if not app_private.support_staff(actor)then raise exception'FORBIDDEN';end if;if p_limit is null or p_limit not between 1 and 100 or(p_state is not null and p_state not in('open','completed','cancelled'))then raise exception'VALIDATION_ERROR';end if;
 select coalesce(jsonb_agg(x.item order by x.id),'[]'::jsonb)into items from(select f.id,jsonb_build_object('follow_up_id',f.id,'learner_id',f.learner_id,'learner_name',p.display_name,'owner',jsonb_build_object('account_id',a.id,'display_name',op.display_name),'due_at',f.due_at,'reason',f.reason,'channel',f.channel,'state',f.state,'version',f.version,'created_at',f.created_at,'completed_at',f.completed_at)item from app_private.follow_ups f join app_private.learners l on l.id=f.learner_id join app_private.people p on p.id=l.person_id join app_private.accounts a on a.id=f.owner_id join app_private.people op on op.id=a.person_id where(app_private.has_role(actor,'admin')or f.owner_id=actor)and(p_learner_id is null or f.learner_id=p_learner_id)and(p_owner_id is null or f.owner_id=p_owner_id)and(p_state is null or f.state=p_state)and(p_cursor is null or f.id>p_cursor)order by f.id limit p_limit)x;
 return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'follow_up_id'else null end);end$$;
do $$declare t text;f record;begin
 foreach t in array array['crm_customers','follow_ups','follow_up_resolutions']loop execute format('alter table app_private.%I enable row level security',t);execute format('create policy commands_access on app_private.%I to git_tutor_commands using(true)with check(true)',t);execute format('revoke all on app_private.%I from public,anon,authenticated,service_role,git_tutor_worker',t);execute format('grant select,insert on app_private.%I to git_tutor_commands',t);if t<>'follow_up_resolutions'then execute format('grant update on app_private.%I to git_tutor_commands',t);else execute format('create trigger immutable_row before update or delete on app_private.%I for each row execute function app_private.reject_immutable_change()',t);end if;end loop;
 for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','app_private')and p.proname=any(array['crm_can_access','crm_customer_dto','list_customers','get_customer','assign_follow_up','complete_follow_up','set_customer_archived','list_crm_owners','list_follow_ups'])loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end$$;
revoke create on schema api,app_private from git_tutor_commands;
